    {"q": "‘Zaif’ hadisni amal qilish hukmi nima?", "options": ["Faqat fazilatlar bobida amal qilinishi mumkin", "Har doim amal qilinadi", "Hech qachon amal qilinmaydi", "Faqat aqidada amal qilinadi"], "answer": "Faqat fazilatlar bobida amal qilinishi mumkin"},
    {"q": "‘Mavzu’ hadisni rivoyat qilish hukmi nima?", "options": ["Joiz", "Harom", "Makruh", "Muboh"], "answer": "Harom"},
    {"q": "Hadisni rivoyat qilishda ‘lafzan’ va ‘ma’nan’ rivoyat nima?", "options": ["So‘zma-so‘z yoki ma’no jihatdan rivoyat qilish", "Yozma yoki og‘zaki rivoyat", "Uzun yoki qisqa rivoyat", "Sahih yoki zaif rivoyat"], "answer": "So‘zma-so‘z yoki ma’no jihatdan rivoyat qilish"},
    {"q": "‘Lafzan’ rivoyat qilish qachon joiz?", "options": ["Har doim", "Roviy hadisning so‘zlarini aniq eslab qolgan bo‘lsa", "Hech qachon", "Faqat yozma rivoyatda"], "answer": "Roviy hadisning so‘zlarini aniq eslab qolgan bo‘lsa"},
    {"q": "‘Ma’nan’ rivoyat qilish qachon joiz?", "options": ["Har doim", "Roviy so‘zlarni aniq eslab qolmagan, lekin ma’noni to‘g‘ri yetkaza olsa", "Hech qachon", "Faqat yozma rivoyatda"], "answer": "Roviy so‘zlarni aniq eslab qolmagan, lekin ma’noni to‘g‘ri yetkaza olsa"},
