    {"q": "‘Asbobul vurud’ ilmi nima?", "options": ["Hadisning rivoyat sabablarini o‘rganadi", "Hadisning isnodini o‘rganadi", "Hadisning matnini o‘rganadi", "Hadisning hukmini o‘rganadi"], "answer": "Hadisning rivoyat sabablarini o‘rganadi"},
    {"q": "‘Muxtaliful hadis’ ilmi nima?", "options": ["O‘zaro zid ko‘rinadigan hadislarni uyg‘unlashtirish", "Zaif hadislarni aniqlash", "Mavzu’ hadislarni aniqlash", "Sahih hadislarni aniqlash"], "answer": "O‘zaro zid ko‘rinadigan hadislarni uyg‘unlashtirish"},
